-- PT120-S3-Q13. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT120-S3-Q13$batch05$ AND q.stimulus=$batch05$Writer: In the diplomat’s or lawyer’s world, a misinterpreted statement can result in an international incident or an undeserved prison term. Thus, legal and diplomatic language is stilted and utterly without literary merit, since by design it prevents misinterpretation, which in these areas can have severe consequences.$batch05$ AND q.prompt=$batch05$The writer's argument requires assuming which one of the following?$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT120-S3-Q13$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT120-S3-Q13$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Legal and diplomatic language is stilted and has no literary merit.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$It is designed to prevent misinterpretation, because misreading it can have severe consequences.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$"Prevents misinterpretation" goes in; "no literary merit" comes out. Why would avoiding misreadings cost a text its literary value? Only if literary qualities are the kind of thing that invites misreading. That is the bridge the writer never builds.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: literary language is more open to misinterpretation than plain language.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT120-S3-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$Negate it: "literary language is *no more* likely to be misunderstood than non-literary language." Then designing against misreading gives no reason to strip out literary merit, and the conclusion loses its support.$batch05$), ($batch05$B$batch05$, $batch05$Which documents are more important never comes up.$batch05$), ($batch05$C$batch05$, $batch05$Comparing lawyers with novelists does not connect misinterpretation to literary merit.$batch05$), ($batch05$D$batch05$, $batch05$Who finds these issues interesting has nothing to do with how the language reads.$batch05$), ($batch05$E$batch05$, $batch05$This is the most tempting wrong answer, because it echoes the idea of care under high stakes. But the argument is about how the language is *designed*, not about people's general caution. Negate it and the argument still runs on the design point.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT120-S3-Q13$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
